query CountLine($where: CountLineWhereInput, $orderBy: [CountLineOrderByInput!], $first: Int, $after: String) {
  countLine(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        count{
          id
          number
          countStatusId
        }
        approvedAt
      }
    }
  }
}

